using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

namespace ProxyService
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private volatile CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 5;
        private DateTime _openedAt = DateTime.MinValue;
        private readonly TimeSpan _recoveryTimeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public CircuitState State
        {
            get
            {
                if (_state == CircuitState.Open && DateTime.UtcNow - _openedAt > _recoveryTimeout)
                {
                    lock (_lock)
                    {
                        if (_state == CircuitState.Open)
                            _state = CircuitState.HalfOpen;
                    }
                }
                return _state;
            }
        }

        public void RecordSuccess()
        {
            lock (_lock)
            {
                _failureCount = 0;
                _state = CircuitState.Closed;
            }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                if (_failureCount >= _threshold)
                {
                    _state = CircuitState.Open;
                    _openedAt = DateTime.UtcNow;
                }
            }
        }
    }

    public class RateLimiter
    {
        private readonly ConcurrentDictionary<string, ClientBucket> _buckets = new();
        private readonly int _maxRequests;
        private readonly TimeSpan _window;

        public RateLimiter(int maxRequests, TimeSpan window)
        {
            _maxRequests = maxRequests;
            _window = window;
        }

        public bool IsAllowed(string clientId)
        {
            var bucket = _buckets.GetOrAdd(clientId, _ => new ClientBucket(_maxRequests, _window));
            return bucket.TryConsume();
        }

        private class ClientBucket
        {
            private readonly int _maxTokens;
            private readonly TimeSpan _window;
            private int _tokens;
            private long _lastRefillTicks;

            public ClientBucket(int maxTokens, TimeSpan window)
            {
                _maxTokens = maxTokens;
                _window = window;
                _tokens = maxTokens;
                _lastRefillTicks = DateTime.UtcNow.Ticks;
            }

            public bool TryConsume()
            {
                Refill();
                var current = Interlocked.Decrement(ref _tokens);
                return current >= 0;
            }

            private void Refill()
            {
                var now = DateTime.UtcNow.Ticks;
                var last = Interlocked.Read(ref _lastRefillTicks);
                var elapsed = TimeSpan.FromTicks(now - last);

                if (elapsed >= _window)
                {
                    if (Interlocked.CompareExchange(ref _lastRefillTicks, now, last) == last)
                    {
                        Interlocked.Exchange(ref _tokens, _maxTokens);
                    }
                }
            }
        }
    }

    public class ProxyHandler
    {
        private readonly HttpClient _httpClient;
        private readonly CircuitBreaker _circuitBreaker;
        private readonly RateLimiter _rateLimiter;
        private readonly ConcurrentDictionary<string, string> _clientIdentityCache = new();

        // Only trust X-Forwarded-For when the request arrives from a known/trusted proxy.
        private readonly bool _trustForwardedHeaders;

        public ProxyHandler(HttpClient httpClient, CircuitBreaker circuitBreaker, RateLimiter rateLimiter, bool trustForwardedHeaders = false)
        {
            _httpClient = httpClient;
            _circuitBreaker = circuitBreaker;
            _rateLimiter = rateLimiter;
            _trustForwardedHeaders = trustForwardedHeaders;
        }

        public string ResolveClientIdentity(HttpRequestMessage request)
        {
            // Always start from the direct (unspoofable) connection IP.
            var directIp = NormalizeAddress(GetDirectClientIp(request));

            // Only honor X-Forwarded-For if the immediate peer is a trusted proxy.
            string clientIp = directIp;
            if (_trustForwardedHeaders && request.Headers.Contains("X-Forwarded-For"))
            {
                var forwarded = request.Headers.GetValues("X-Forwarded-For").FirstOrDefault();
                if (!string.IsNullOrWhiteSpace(forwarded))
                {
                    // Take the left-most (original client) entry from the proxy chain.
                    var firstHop = forwarded.Split(',').FirstOrDefault()?.Trim();
                    var normalized = NormalizeAddress(firstHop);
                    if (normalized != "unknown")
                        clientIp = normalized;
                }
            }

            var apiKey = request.Headers.Contains("X-Api-Key")
                ? request.Headers.GetValues("X-Api-Key").FirstOrDefault()
                : null;

            // Use composite identity: prefer API key, fall back to IP
            var identity = apiKey ?? clientIp;

            // Cache identity resolution for performance. Key on the resolved,
            // trust-checked values rather than raw attacker-controlled headers.
            return _clientIdentityCache.GetOrAdd(GetCacheKey(clientIp, apiKey), _ => identity);
        }

        private string GetCacheKey(string clientIp, string apiKey)
        {
            return $"{clientIp}|{apiKey ?? ""}";
        }

        private string NormalizeAddress(string address)
        {
            if (address == null) return "unknown";
            // Strip port if present
            if (address.Contains(':') && !address.Contains("::")
                && address.LastIndexOf(':') == address.IndexOf(':'))
            {
                address = address.Substring(0, address.IndexOf(':'));
            }
            var trimmed = address.Trim().ToLowerInvariant();
            return string.IsNullOrEmpty(trimmed) ? "unknown" : trimmed;
        }

        private string GetDirectClientIp(HttpRequestMessage request)
        {
            if (request.Properties.ContainsKey("ClientIp"))
                return request.Properties["ClientIp"] as string ?? "unknown";
            return "unknown";
        }

        public async Task<HttpResponseMessage> HandleRequest(HttpRequestMessage request)
        {
            var clientId = ResolveClientIdentity(request);

            // Check circuit breaker first
            if (_circuitBreaker.State == CircuitState.Open)
            {
                return new HttpResponseMessage(HttpStatusCode.ServiceUnavailable)
                {
                    Content = new StringContent("Service temporarily unavailable")
                };
            }

            // Rate limit check - always enforced regardless of circuit state
            if (!_rateLimiter.IsAllowed(clientId))
            {
                return new HttpResponseMessage(HttpStatusCode.TooManyRequests)
                {
                    Content = new StringContent("Rate limit exceeded")
                };
            }

            // Additional check: only allow one probe in HalfOpen state
            if (_circuitBreaker.State == CircuitState.HalfOpen)
            {
                // Still rate-limited, but proceed with the request as a probe
            }

            try
            {
                var response = await _httpClient.SendAsync(request);
                _circuitBreaker.RecordSuccess();
                return response;
            }
            catch (Exception)
            {
                _circuitBreaker.RecordFailure();
                return new HttpResponseMessage(HttpStatusCode.BadGateway)
                {
                    Content = new StringContent("Upstream service error")
                };
            }
        }
    }
}
